?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Search Console SEO | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f6f8fb;color:#1f2937}.wrap{max-width:1280px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.card,.panel{background:#fff;border:1px solid #dde5ee;border-radius:14px;padding:16px}.kpi{font-size:28px;font-weight:800}.muted{color:#64748b;font-size:13px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.tabs button{padding:8px 12px;border:1px solid #d7e0e8;background:#fff;border-radius:9px;cursor:pointer}.tabs button.active{background:#123b67;color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:8px;border-bottom:1px solid #edf2f7;text-align:left}.table th{cursor:pointer}.controls{display:flex;gap:8px;flex-wrap:wrap}input,select,textarea,button{font:inherit}.controls input,.controls select{padding:8px;border:1px solid #cfd8e3;border-radius:8px}button.primary{background:#123b67;color:#fff;border:0;padding:9px 14px;border-radius:9px}.bar{height:8px;background:#e6edf3;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:#64748b}.chart{display:flex;align-items:flex-end;gap:3px;height:120px;padding-top:10px}.chart i{flex:1;min-width:2px;background:#64748b;border-radius:2px 2px 0 0}.wide{grid-column:1/-1}@media(max-width:800px){.cards,.grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.cards,.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1>Google Search Console SEO</h1><div class="muted" id="refresh">Data source: not loaded</div></div><div class="controls"><select id="days"><option value="7">7 days</option><option value="28" selected>28 days</option><option value="90">90 days</option></select><button class="primary" id="reload">Refresh</button><button id="export">Export CSV</button></div></div><div class="cards"><div class="card"><div class="muted">Clicks</div><div class="kpi" id="clicks">0</div><div class="muted" id="clickDelta"></div></div><div class="card"><div class="muted">Impressions</div><div class="kpi" id="impressions">0</div><div class="muted" id="imprDelta"></div></div><div class="card"><div class="muted">CTR</div><div class="kpi" id="ctr">0%</div></div><div class="card"><div class="muted">Avg position</div><div class="kpi" id="position">0</div></div></div><div class="panel wide"><h2>Trend</h2><div class="chart" id="chart"></div></div><div class="grid"><div class="panel"><h2>Quick wins: positions 11–30</h2><div id="wins" class="tablewrap"></div></div><div class="panel"><h2>Declining pages</h2><div id="declines" class="tablewrap"></div></div><div class="panel"><h2>New queries</h2><div id="newq" class="tablewrap"></div></div><div class="panel"><h2>Import Search Console rows</h2><p class="muted">Paste JSON rows exported from Google Search Console/API. Each row can include date, query, page, country, device, search_appearance, clicks, impressions, ctr and position.</p><div class="controls"><input id="from" type="date"><input id="to" type="date"><input id="property" placeholder="Property URI"></div><textarea id="payload" rows="8" style="width:100%;margin-top:8px" placeholder='[{"date":"2026-09-01","query":"crm software saudi","page":"https://techselectai.com/software/example","clicks":2,"impressions":100,"ctr":0.02,"position":14.2}]'></textarea><button class="primary" id="importBtn">Import</button><div class="muted" id="importMsg"></div></div><div class="panel wide"><h2>Top queries</h2><div id="queries" class="tablewrap"></div></div><div class="panel wide"><h2>Top pages</h2><div id="pages" class="tablewrap"></div></div></div></div><script>let data=null,csrf='';const n=v=>Number(v||0),pct=v=>(n(v)*100).toFixed(1)+'%',fmt=v=>Math.round(n(v)).toLocaleString(),delta=(a,b)=>{a=n(a);b=n(b);if(!b)return a?'new':'0%';return ((a-b)/b*100).toFixed(1)+'% vs previous';};function table(rows,label){if(!rows?.length)return '<div class="muted">No data</div>';return '<table class="table"><thead><tr><th>'+label+'</th><th>Clicks</th><th>Impr.</th><th>CTR</th><th>Pos.</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+String(r.dimension??r.query??r.page??'')+'</td><td>'+fmt(r.clicks??r.current_clicks)+'</td><td>'+fmt(r.impressions??r.current_impressions)+'</td><td>'+pct(r.ctr)+'</td><td>'+n(r.position).toFixed(1)+'</td></tr>').join('')+'</tbody></table>';}async function load(){const days=document.getElementById('days').value;const r=await fetch('/api/search-console?days='+days,{credentials:'same-origin'}),j=await r.json();if(!r.ok){alert(j.error||'Load failed');return;}data=j;csrf=j.csrf_token||csrf;clicks.textContent=fmt(j.summary.clicks);impressions.textContent=fmt(j.summary.impressions);ctr.textContent=pct(j.summary.ctr);position.textContent=n(j.summary.position).toFixed(1);clickDelta.textContent=delta(j.summary.clicks,j.previous_summary.clicks);imprDelta.textContent=delta(j.summary.impressions,j.previous_summary.impressions);refresh.textContent=j.last_refresh?'Data source: '+j.last_refresh.source_label+' · refreshed '+j.last_refresh.imported_at:'Data source: no Search Console import yet';queries.innerHTML=table(j.queries,'Query');pages.innerHTML=table(j.pages,'Page');wins.innerHTML=table(j.quick_wins,'Query');declines.innerHTML=table(j.declining_pages,'Page');newq.innerHTML=table(j.new_queries,'Query');const max=Math.max(1,...j.daily.map(x=>n(x.impressions)));chart.innerHTML=j.daily.map(x=>'<i title="'+x.date+' · '+fmt(x.impressions)+' impressions" style="height:'+Math.max(2,n(x.impressions)/max*100)+'%"></i>').join('');}reload.onclick=load;days.onchange=load;importBtn.onclick=async()=>{let rows;try{rows=JSON.parse(payload.value)}catch(e){importMsg.textContent='Invalid JSON';return;}const body={source_label:'google_search_console_manual',property_uri:property.value,date_from:from.value,date_to:to.value,rows};const r=await fetch('/api/search-console/import',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)}),j=await r.json();importMsg.textContent=r.ok?'Imported '+j.rows_imported+' rows':(j.error||'Import failed');if(r.ok)load();};export.onclick=()=>{if(!data)return;const rows=[['type','name','clicks','impressions','ctr','position'],...data.queries.map(r=>['query',r.dimension,r.clicks,r.impressions,r.ctr,r.position]),...data.pages.map(r=>['page',r.dimension,r.clicks,r.impressions,r.ctr,r.position])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='techselectai-search-console.csv';a.click();URL.revokeObjectURL(a.href);};load();</script></body></html>